59	AbstractDiskWriter::AbstractDiskWriter(const std::string& filename)
60	    : filename_(filename),
61	      fd_(A2_BAD_FD),
62	#ifdef __MINGW32__
63	      mapView_(0),
64	#else  // !__MINGW32__
65	#endif // !__MINGW32__
66	      readOnly_(false),
67	      enableMmap_(false),
68	      mapaddr_(nullptr),
69	      maplen_(0)
