77	// Returns error code depending on the platform. For MinGW32, return
78	// the value of GetLastError(). Otherwise, return errno.
79	int fileError()
80	{
81	#ifdef __MINGW32__
82	  return GetLastError();
83	#else  // !__MINGW32__
84	  return errno;
85	#endif // !__MINGW32__
86	}
