236	void AbstractDiskWriter::openExistingFile(int64_t totalLength)
237	{
238	  int flags = O_BINARY;
239	  if (readOnly_) {
240	    flags |= O_RDONLY;
241	  }
242	  else {
243	    flags |= O_RDWR;
244	  }
245	  fd_ = openFileWithFlags(filename_, flags, error_code::FILE_OPEN_ERROR);
246	}
