59	void ByteArrayDiskWriter::writeData(const unsigned char* data,
60	                                    size_t dataLength, int64_t offset)
61	{
62	  if (offset + dataLength > maxLength_) {
63	    throw DL_ABORT_EX(fmt("Maximum length(%lu) exceeded.",
64	                          static_cast<unsigned long>(maxLength_)));
65	  }
66	  int64_t length = size();
67	  if (length < offset) {
68	    buf_.seekp(length, std::ios::beg);
69	    for (int64_t i = length; i < offset; ++i) {
70	      buf_.put('\0');
71	    }
72	  }
73	  else {
74	    buf_.seekp(offset, std::ios::beg);
75	  }
76	  buf_.write(reinterpret_cast<const char*>(data), dataLength);
77	}
